    Bug 1949120 - Get unread and total message counts directly from the database. r=mkmelin
    (…for Panorama only.)

    nsMsgDBFolder keeps cached counts of messages. There's no need for this when we can ask the
    database to count the messages, and it doesn't get initialised with the new database anyway.

    Differential Revision: https://phabricator.services.mozilla.com/D249934

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index a168dea9db6..af264373dde 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -3814,6 +3814,16 @@ NS_IMETHODIMP nsMsgDBFolder::GetNumUnread(bool deep, int32_t* numUnread) {
   bool isServer = false;
   nsresult rv = GetIsServer(&isServer);
   NS_ENSURE_SUCCESS(rv, rv);
+#ifdef MOZ_PANORAMA
+  if (!isServer && Preferences::GetBool("mail.panorama.enabled", false)) {
+    nsCOMPtr<nsIMsgDatabase> db;
+    nsCOMPtr<nsIDBFolderInfo> folderInfo;
+    rv = GetDBFolderInfoAndDB(getter_AddRefs(folderInfo), getter_AddRefs(db));
+    if (NS_SUCCEEDED(rv)) {
+      folderInfo->GetNumUnreadMessages(&mNumUnreadMessages);
+    }
+  }
+#endif  // MOZ_PANORAMA
   int32_t total = isServer ? 0 : mNumUnreadMessages + mNumPendingUnreadMessages;

   if (deep) {
@@ -3842,6 +3852,16 @@ NS_IMETHODIMP nsMsgDBFolder::GetTotalMessages(bool deep,
   bool isServer = false;
   nsresult rv = GetIsServer(&isServer);
   NS_ENSURE_SUCCESS(rv, rv);
+#ifdef MOZ_PANORAMA
+  if (!isServer && Preferences::GetBool("mail.panorama.enabled", false)) {
+    nsCOMPtr<nsIMsgDatabase> db;
+    nsCOMPtr<nsIDBFolderInfo> folderInfo;
+    rv = GetDBFolderInfoAndDB(getter_AddRefs(folderInfo), getter_AddRefs(db));
+    if (NS_SUCCEEDED(rv)) {
+      folderInfo->GetNumMessages(&mNumTotalMessages);
+    }
+  }
+#endif  // MOZ_PANORAMA
   int32_t total = isServer ? 0 : mNumTotalMessages + mNumPendingTotalMessages;

   if (deep) {
